import type { ResidualReading } from "../../shared/gates.ts";
import type { DiffResult, GateResult, PolicyFinding } from "../../shared/types.ts";
import type { HandoffSummary, PrepHandoffSummary } from "./types.ts";
import { prepHandoffBlock } from "./prep.ts";
import { measurements, readLedger, renderValley, valley } from "../../../../tools/agent/experimentLedger.ts";
import { renderClosed } from "../../../../tools/agent/closedDirections.ts";
import { lookupSignature } from "../../../../tools/agent/residualSignatures.ts";

export const DECOMPILE_SKILL = "psx-decompile-function";

/**
 * The nudge the loop sends on every return that is not yet a match.
 *
 * It states the protocol rather than offering encouragement. A turn told only
 * to keep going will often spend most of its context reasoning forward from the
 * last report — building a chain about what the compiler would do, several
 * unmeasured steps deep, before making any edit at all. Naming the four steps
 * each time costs a few lines and is the difference between a turn that
 * produces a measurement and one that produces an argument.
 */
export const KEEP_GOING = [
  "Keep going — there is clean C that matches this function 100%, and you stop only when it does.",
  "",
  "One experiment is one edit and one measurement:",
  "1. OBSERVE — run one tool. Three bullets of what it printed. No inference.",
  "2. HYPOTHESISE — one sentence: <edit> should lower <term> in block <n>, because <mechanism>.",
  "3. ACT — make that one edit and nothing else.",
  "4. MEASURE — psx_residual_objective, then start the next experiment immediately.",
  "",
  "Run them back to back. Do not stop to summarise, and do not defer an experiment",
  "you can already name — running it costs less than describing it.",
].join("\n");

/**
 * What the turn is told about where it stands.
 *
 * The verdict decides; the word count is context. What the turn should *steer
 * by* is the residual: it names the pass that owns the difference and the block
 * to work next, and unlike the word count it goes down when the source moves
 * toward the target rather than when the registers happen to line up.
 */
/**
 * Distinct measurements with no improvement before the current axis counts as
 * exhausted, and before the whole spelling family does.
 *
 * The first is the point at which re-spelling one axis stops being search and
 * starts being repetition. The second is calibrated against a real stalled
 * ledger: the session that produced it ran seventeen distinct programs without
 * an improvement while arguing the residual was unreachable, and improved
 * steadily for the fifteen before that.
 */
const AXIS_EXHAUSTED = 3;
const SPELLING_EXHAUSTED = 8;

/**
 * Whether the last few measurements moved the residual at all.
 *
 * Read from the ledger rather than from loop state, because the ledger is what
 * survives a context clear and a model change. Three measurements with no
 * improvement is the point at which re-spelling the same axis stops being
 * search and starts being repetition.
 */
function stallLine(functionName: string): string | undefined {
  /* Respellings are excluded: a source that reaches an already-measured
   * program is not a measurement that failed to move, it is the same program
   * arrived at again. Counting them as failures makes a loop that is opening
   * its own search space look like a loop that has run out of ideas. */
  const rows = readLedger(functionName);
  const entries = measurements(rows);
  if (entries.length < 4) return undefined;

  const better = (left: number[], right: number[]): boolean => {
    for (let index = 0; index < Math.max(left.length, right.length); index++) {
      const difference = (left[index] ?? 0) - (right[index] ?? 0);
      if (difference !== 0) return difference < 0;
    }
    return false;
  };

  let best = entries[0]!.key;
  let lastImprovement = 0;
  entries.forEach((entry, index) => {
    if (index > 0 && better(entry.key, best)) {
      best = entry.key;
      lastImprovement = index;
    }
  });
  const since = entries.length - 1 - lastImprovement;
  if (since < AXIS_EXHAUSTED) return undefined;

  /* Before the escalation list, because it changes what the list is for. The
   * heavier tools below all answer "is this source's output reachable"; in a
   * valley the useful question is what the original's output requires, and
   * running the first set at the second question wastes the escalation. */
  const shape = valley(rows);
  const lines = [
    ...(shape ? [renderValley(shape).join(" ")] : []),
    `STALLED: ${since} distinct measurements since the residual last improved on ` +
    `[${best.join(", ")}]. The axis is exhausted, not the function — stop re-spelling it and ` +
    "bring heavier evidence.",
    "Audit the premises first, because everything else is conditioned on them and cannot see " +
    "them: psx_callee_truth confronts every callee declaration in scope with the vendored SDK " +
    "headers and the callees' own code, psx_sdk_idioms does the same for operation boundaries. " +
    "A wrong declaration adds call setup no rewrite of this body can remove, and every " +
    "measurement taken under it scored a different program.",
    "Then read the pass that decides the residual before writing another spelling: its psx_reference " +
    "sheet, or the deciding function itself through psx_compiler_source. After that, enumerate the source " +
    "space (psx_search_source_shapes) or solve for the compiler state instead of modelling it " +
    "(psx_solve_local_allocation, psx_search_scheduler_state, psx_allocator_counterfactual). A solver result is a " +
    "specification for a source shape, and an UNSAT is a real finding that closes a direction. " +
    "Record what each one closed with psx_record_closed, and read that record before you run one " +
    "— a direction another session already closed costs minutes to close again. When a search " +
    "reports no exact candidate, that is not the end " +
    "of its output: read the per-class residual axes and the runs each class moved, and take the " +
    "next experiment from the axis that moved rather than from the match count. Before trusting " +
    "any search verdict, check its caveats for constructs the grammar refused, its axis-effect " +
    "block for axes that are counted but inert, and its coverage — a --derive-only run sampled, " +
    "and a sample supports no statement about the domain.",
  ];

  /* Past this point the loop has produced many genuinely different programs
   * and moved nothing, which is not evidence that the residual is hard. It is
   * evidence that the answer is not a spelling, and the tools above cannot say
   * so: they all answer whether the current source's output is reachable, and
   * the open question has become what the original source was. */
  if (since >= SPELLING_EXHAUSTED) {
    lines.push(
      `${since} distinct programs is past the point where more variation is informative. ` +
      "Exhausting a spelling family is a positive result: the answer is not a spelling. Switch " +
      "to the author's frame, which the compiler-side tools cannot reach. The vendored SDK " +
      "headers give the real signature and the real operation for anything the SDK provides — " +
      "read the header rather than your reconstruction of what the disassembly implies it must " +
      "say. The already-matched functions in this target's file group are the only record of how " +
      "this author wrote code: which locals they kept live, how they walked an array, what they " +
      "hoisted, whether they took a base pointer once or re-indexed each time. A byte-exact " +
      "neighbour is a proven idiom. notes/file-groupings.md names the group; read three of its " +
      "members before reading another pass. A residual that survives every rewrite of your own " +
      "idiom is usually somebody else's idiom.",
    );
  }
  return lines.join(" ");
}

export function matchReport(diff: DiffResult, residual?: ResidualReading | null): string {
  /* A stub is not a position in the search. Reporting it as one — "0/479
     words" under a verdict the reader skims — is how a turn spends itself
     analysing a diff of the original against nothing. */
  if (diff.verdict === "stub") {
    return [
      `Oracle: ${diff.functionName} verdict STUB — the source still hands the function to the assembler.`,
      "No C has been written for it yet, so there is no candidate program, no word count and no residual.",
      "Write the function body. Every number below the verdict starts existing once you do.",
    ].join("\n");
  }

  const lines = [
    `Oracle: ${diff.functionName} verdict ${diff.verdict.toUpperCase()} — ${diff.matchedInstructions}/${diff.totalInstructions} words (${diff.matchPercent}%).`,
  ];
  if (diff.instructionCountDelta !== 0) {
    lines.push(
      `Instruction count delta versus target: ${diff.instructionCountDelta > 0 ? "+" : ""}${diff.instructionCountDelta}.`,
    );
  }
  if (residual && !residual.objective.exact) {
    const { controlFlow, population, schedule, allocation } = residual.objective;
    const undetermined = residual.objective.undetermined ?? 0;
    const blind = residual.objective.blindBlocks ?? [];
    lines.push(
      `Residual (steer by this, not the word count): control-flow ${controlFlow}, population ${population}, ` +
      `schedule ${schedule}, allocation ${allocation}.`,
    );
    if (undetermined > 0) {
      lines.push(
        `${undetermined} word(s) are UNDETERMINED — a relocation whose symbol has no known address. ` +
        (blind.length > 0
          ? `Block ${blind.join(", ")} contain${blind.length === 1 ? "s" : ""} them and ${blind.length === 1 ? "is" : "are"} excluded from the residual above: ` +
            "their terms are an artifact of the unresolved relocation, and no source edit moves them. "
          : "") +
        "This is a configuration defect, not a source one. The usual cause is a jump table with no " +
        "`.rodata` attribution in the container's splat config — `npx tsx tools/build/deriveRodataSplits.ts " +
        "--container <id>` says so, and the build's link rule rederives it. Fix that before rewriting anything.",
      );
    }
    if ((population > 0 || controlFlow > 0) && !(population === 0 && blind.length > 0)) {
      lines.push("The two programs do not contain the same instructions, so no allocation or scheduling reading applies yet — fix the semantics first.");
    }
    const next = residual.work[0];
    if (next) {
      lines.push(
        `Next block: ${next.block.block}` +
        `${next.block.vram === undefined ? "" : ` (0x${next.block.vram.toString(16).toUpperCase()})`}` +
        ` — population ${next.block.population}, schedule ${next.block.schedule}, ` +
        `allocation ${next.block.allocation + next.block.coalescing}. ${next.reason}`,
      );
      if (next.duplicates.length > 0) {
        lines.push(`Fixing it should also close block ${next.duplicates.join(", ")}.`);
      }
      /* The same residual shape in another function is the strongest evidence
         this project can offer, and it used to be computed and discarded. */
      const precedent = next.block.signature
        ? lookupSignature(next.block.signature, diff.functionName)
        : "";
      if (precedent) lines.push("", precedent);
    }
    lines.push("`psx_reverse_pipeline` gives the decisions, their source levers and the mechanism sheet to load; " +
      "`psx_residual_objective` with a source ranks candidate edits and records them.");
    const stalled = stallLine(diff.functionName);
    if (stalled) lines.push("", stalled);
  }
  return lines.join("\n");
}

export function gateReport(gate: GateResult): string {
  return [
    `Finalize oracle failed for ${gate.functionName}:`,
    ...gate.failures.map((failure) => `- ${failure}`),
  ].join("\n");
}

export function findingsReport(findings: PolicyFinding[]): string {
  return findings
    .map((finding) => `- ${finding.file}:${finding.line ?? "?"} — ${finding.kind} — ${finding.message}\n    ${finding.text ?? ""}`)
    .join("\n");
}

/**
 * The message that opens work on a function.
 *
 * It carries the protocol, because with `returnsPerTier` at 1 it is the only
 * message an agent ever receives — `nudgeMessage` is sent from the second
 * return onward and never fires. A protocol that lives only in the nudge is a
 * protocol nothing reads.
 *
 * The pacing is stated here in the harness's own vocabulary. "Turn" means one
 * assistant response to this harness and one loop iteration in the skill, and
 * an agent that resolves the two the wrong way concludes it owes exactly one
 * measurement — which is what happened: 30 minutes of work, one measurement, a
 * classification report, and a named next experiment left unrun.
 */
export function openingMessage(functionName: string): string {
  return [
    `/skill:${DECOMPILE_SKILL} Target: ${functionName}. Mode: fresh decompilation.`,
    "Start from the prepared packet below; its measured source is primary. Never replace an existing clean-C attempt with a generated draft.",
    "",
    "Do not stop until the function is byte-exact and psx_finalize_function passes.",
    "Run experiments back to back — one edit and one psx_residual_objective call each,",
    "as many as it takes — without pausing to summarise, check in, or report progress.",
    "The single-experiment rule is about attribution, never about pace: there is no",
    "budget of one measurement, and no good stopping point short of a match.",
    "",
    "If you can name the next experiment, run it. A compile is under a second, so",
    "'next experiment, when resuming' is always the wrong sentence — the run costs",
    "less than writing that down. Classify once at the start; after that every",
    "diagnostic must be followed by an edit and a measurement before the next one.",
    "Reading the mechanism sheet or compiler function a diagnostic points at is part of",
    "that diagnostic, not another one.",
    "",
    "Return only when the function is byte-exact, or when something genuinely needs a",
    "human decision (an allowlist entry, a policy exception) — then say which, briefly.",
    "Do not commit or create a worktree. Candidate experiments may live under build/; integration is scoped to this function's src/, include/, and configs/ inputs.",
  ].join(" ");
}

/**
 * The outgoing tier's exit interview.
 *
 * It runs on that tier's own model with its context still intact — the last
 * moment the reasoning exists anywhere. Everything after this point reads the
 * source file, the oracle report, and this summary, and nothing else.
 */
export function handoffMessage(functionName: string): string {
  return [
    `You have not reached a byte-exact match for ${functionName}, and the loop is escalating to a`,
    "stronger model. Your context ends here; the next tier will see only the source file on disk,",
    "the oracle report, and the summary you are about to write.",
    "",
    `Call \`${"psx_loop_handoff"}\` exactly once with four fields:`,
    "",
    "- **whatWasTried** — the source shapes and structural hypotheses you actually compiled and",
    "  diffed, and what each one did to the diff. Not what you considered; what you measured.",
    "- **ruledOut** — hypotheses you positively eliminated, each with the evidence that killed it.",
    "  This is the most valuable field: it is what stops the next tier repeating your work.",
    "- **currentDivergence** — the first remaining divergence. Where it is, what the target does",
    "  there, what your candidate does instead.",
    "- **leadingHypothesis** — the most promising direction you did not get to, and the cheapest",
    "  evidence that would confirm or kill it.",
    "",
    "Every claim must be traceable to an assembly line or a tool that measured it. A hunch you",
    "cannot point at is worse than an empty field — it will be read as a finding. Do not edit any",
    "files in this turn.",
  ].join("\n");
}

/**
 * How the incoming tier is told to read that summary.
 *
 * The previous tier failed, so at least one premise it was working from is
 * probably wrong — and a summary written by a failed attempt is exactly the
 * kind of plausible, confident, wrong context that makes the next attempt fail
 * the same way. It is offered as a lead to disprove, never as a foundation.
 */
export function handoffBlock(summary: HandoffSummary): string {
  const body =
    summary.source === "tool"
      ? [
          `- What was tried: ${summary.whatWasTried}`,
          `- Ruled out: ${summary.ruledOut}`,
          `- Current divergence: ${summary.currentDivergence}`,
          `- Leading hypothesis: ${summary.leadingHypothesis}`,
        ].join("\n")
      : summary.whatWasTried;

  return [
    "--- Handoff from the previous escalation tier ---",
    "",
    body,
    "",
    "--- How to read the above ---",
    "",
    "Treat this analysis adversarially and with skepticism. It was written by a tier that did not",
    "match the function, so at least one premise in it is likely wrong, and the wrong ones will be",
    "stated as confidently as the right ones. Use it to avoid repeating measurements, not to",
    "inherit conclusions. Re-derive every structural premise — arity, frame, types, ownership —",
    "from the tools and the assembly. Where the summary and the assembly disagree, the assembly",
    "wins and the summary was wrong.",
    "",
    "In particular, a hypothesis listed as ruled out is only ruled out if the evidence given",
    "actually rules it out. Check the evidence, not the verdict. Most eliminations are",
    "conditional without saying so: a source form shown to be unreachable under the schedule or",
    "allocation the previous tier happened to produce is not unreachable when that state is",
    "itself the thing you are changing. Re-read every 'proven blocked' with that in mind.",
  ].join("\n");
}

export function escalationMessage(
  functionName: string,
  tierLabel: string,
  lastReport: string,
  handoff?: HandoffSummary,
  preparedOpening = "",
  prepHandoff?: PrepHandoffSummary,
): string {
  return [
    `/skill:${DECOMPILE_SKILL} Target: ${functionName}. Mode: resume/fix.`,
    prepHandoff
      ? `The preparation tier has handed off its candidate and context; you are now ${tierLabel}, the matching tier.`
      : `The previous escalation tier did not reach a match; you are now ${tierLabel}.`,
    preparedOpening
      ? "Start from the measured candidate below, not an untouched live stub or regenerated draft. Preserve its edits and header work; classify its diff once."
      : "Preserve the current clean-C attempt, classify its existing diff once, and continue from there.",
    "Re-derive the structural premises rather than trusting the previous tier's conclusions —",
    "but read psx_experiment_ledger first: re-deriving a classification is warranted, re-running",
    "an experiment it already records is not.",
    "",
    lastReport,
    ...(preparedOpening ? ["", preparedOpening] : []),
    ...(closedBlock(functionName) ? ["", closedBlock(functionName)] : []),
    ...(handoff ? ["", handoffBlock(handoff)] : []),
    ...(prepHandoff ? ["", prepHandoffBlock(prepHandoff)] : []),
    "",
    KEEP_GOING,
  ].join("\n");
}

/**
 * What earlier sessions already proved about this function's search space.
 *
 * Carried into every escalation because that is the message a fresh tier reads
 * first, and a fresh tier is exactly who re-runs a solver that has already
 * answered. An UNSAT rediscovered is minutes bought twice.
 */
function closedBlock(functionName: string): string {
  return renderClosed(functionName);
}

export function nudgeMessage(lastReport: string): string {
  return [KEEP_GOING, "", lastReport].join("\n");
}

/**
 * The one turn between a match and its commit.
 *
 * Grouping evidence is cheapest to record while the function is still in
 * context and most expensive to recover once it is not. The turn is scoped to
 * the ledger on purpose: the build inputs have just been proven, and anything
 * this turn writes outside `notes/` is reverted before the commit.
 */
export function groupingsMessage(functionName: string): string {
  return [
    `/skill:psx-post-decompile-documentation Target: ${functionName}. Documentation role, not solver role.`,
    `${functionName} is byte-exact and has passed the full finalize gate. Read the verified source and supplied evidence.`,
    "Do not commit. Notes-only finalization does not authorize a commit.",
    "",
    "Update `notes/file-groupings.md` if — and only if — this function",
    "produced new evidence about which original translation unit it belongs to. Same-file",
    "evidence is things like a shared static or global cluster, a register-variable quirk",
    "shared with a neighbour, a declaration-order effect, an SDK idiom cluster, or an",
    "adjacency the call graph and the link order agree on.",
    "",
    "Record membership and one-line roles only. Technique and per-function detail belong in",
    "`notes/research/` or `notes/retros/`, not in the ledger.",
    "",
    "If this function produced no new grouping evidence, say so and change nothing — an",
    "unfounded ledger entry is worse than no entry.",
    "",
    "Edit nothing outside `notes/` in this turn. The source has already been verified and any",
    "other edit invalidates the gate and requires re-verification; documentation will remain pending.",
  ].join("\n");
}

export function reviewMessage(functionName: string, findings: PolicyFinding[], sourcePath = `src/${functionName}.c`): string {
  return [
    `Policy review for ${functionName}. A lower escalation tier introduced source constructs the`,
    "clean-source policy forbids for an ordinary compiled function:",
    "",
    findingsReport(findings),
    "",
    "Read `" + sourcePath + "`, the original assembly, and the project's clean-source policy in",
    "AGENTS.md. Decide one question only: is the forbidden construct the",
    "correct answer for this function — a genuine, documented exception class — or is it a workaround",
    "for a structural hypothesis the tier failed to find?",
    "",
    "An exemption asserts permanently, to every later agent, that the construct is correct here.",
    "Being stuck is not that assertion. Approve only on positive evidence; reject by default.",
    "",
    "Answer by calling `psx_loop_policy_verdict` exactly once. Do not edit any files in this turn.",
  ].join("\n");
}

export function rejectionReport(functionName: string, findings: PolicyFinding[], rationale: string): string {
  return [
    `Policy review rejected the forbidden constructs in ${functionName}; the edit has been reverted.`,
    "",
    findingsReport(findings),
    "",
    `Reviewer rationale: ${rationale.trim() || "(none given)"}`,
    "",
    "Do not reintroduce them. The remaining divergence has a clean-C expression; find it.",
  ].join("\n");
}

import type { ExtensionAPI } from "@earendil-works/pi-coding-agent";
import { Type } from "typebox";
import { runProjectCommand, validateFunctionName } from "./shared.ts";

export function registerAnalyzeTargetScheduleTool(pi: ExtensionAPI): void {
  pi.registerTool({
    name: "psx_analyze_target_schedule",
    label: "PSX Target Schedule Analysis",
    description: "Align target/candidate machine instructions through zero-width RTL nodes, explain exact legacy-scheduler priority/dependency/LUID ties, replay bounded target orders, and emit allocation, scheduling, and delay-slot requirements. Diagnostic only; never edits source. Output is limited to 50 KB or 2000 lines.",
    parameters: Type.Object({
      functionName: Type.String({ description: "Exact function symbol to analyze" }),
      block: Type.Optional(Type.Integer({ minimum: 0, maximum: 10000, description: "Optional basic block focus" })),
      maxInterventions: Type.Optional(Type.Integer({ minimum: 1, maximum: 8, description: "Maximum abstract intervention alternatives per requirement" })),
    }),
    async execute(_toolCallId, params, signal, onUpdate, ctx) {
      validateFunctionName(params.functionName);
      const args = ["tsx", "tools/agent/analyzeTargetSchedule.ts", params.functionName];
      if (params.block !== undefined) args.push("--block", String(params.block));
      if (params.maxInterventions !== undefined) args.push("--max-interventions", String(params.maxInterventions));
      onUpdate?.({ content: [{ type: "text", text: `Analyzing target schedule for ${params.functionName}...` }], details: {} });
      return runProjectCommand(pi, ctx.cwd, "npx", args, signal, 120_000);
    },
  });
}

import type { ExtensionAPI } from "@earendil-works/pi-coding-agent";
import { Type } from "typebox";
import { runProjectCommand } from "./shared.ts";

export function registerCallGraphTool(pi: ExtensionAPI): void {
  pi.registerTool({
    name: "psx_build_call_graph",
    label: "Build PSX Call Graph",
    description: "Regenerate the PlayStation project's call graph and priority worklist with tools/agent/callGraph.ts. Output is limited to 50 KB or 2000 lines.",
    parameters: Type.Object({}),
    async execute(_toolCallId, _params, signal, onUpdate, ctx) {
      onUpdate?.({ content: [{ type: "text", text: "Rebuilding the call graph..." }], details: {} });
      return runProjectCommand(
        pi,
        ctx.cwd,
        "npx",
        ["tsx", "tools/agent/callGraph.ts"],
        signal,
        120_000,
      );
    },
  });
}

import type { ExtensionAPI } from "@earendil-works/pi-coding-agent";
import { Type } from "typebox";
import { runProjectCommand, validateFunctionName } from "./shared.ts";

export function registerCompilerTraceTool(pi: ExtensionAPI): void {
  pi.registerTool({
    name: "psx_compiler_trace",
    label: "PSX Compiler Trace",
    description: "Run the configured compiler trace for one PlayStation function and summarize pseudo provenance, observed SET/use/death UIDs, reconstructed lifetime endpoints, allocation, scheduler decisions, hard-register hazards, and target-register recurrence hints. Writes a typed report.json artifact. Output is limited to 50 KB or 2000 lines.",
    parameters: Type.Object({
      functionName: Type.String({ description: "Exact function symbol to trace" }),
      pseudo: Type.Optional(Type.Integer({ minimum: 80, description: "Optional pseudo number for focused provenance output" })),
      schedulerWindow: Type.Optional(Type.String({ pattern: "^\\d+:\\d+$", description: "Optional inclusive scheduler cycle window, for example 24:32" })),
    }),
    async execute(_toolCallId, params, signal, onUpdate, ctx) {
      validateFunctionName(params.functionName);
      onUpdate?.({ content: [{ type: "text", text: `Tracing ${params.functionName}...` }], details: {} });
      const args = ["tsx", "tools/agent/compilerTrace.ts", params.functionName];
      if (params.pseudo !== undefined) args.push("--pseudo", String(params.pseudo));
      if (params.schedulerWindow) args.push("--scheduler-window", params.schedulerWindow);
      return runProjectCommand(
        pi,
        ctx.cwd,
        "npx",
        args,
        signal,
        30_000,
      );
    },
  });
}

import type { ExtensionAPI } from "@earendil-works/pi-coding-agent";
import { Type } from "typebox";
import { runProjectCommand, validateFunctionName } from "./shared.ts";

export function registerExplainDiffTool(pi: ExtensionAPI): void {
  pi.registerTool({
    name: "psx_explain_diff",
    label: "Explain PSX Diff",
    description: "Classify a PlayStation function mismatch by instruction selection, allocation, operand order, scheduling, relocation, or mixed causes. Output is limited to 50 KB or 2000 lines.",
    parameters: Type.Object({
      functionName: Type.String({ description: "Exact function symbol whose mismatch should be classified" }),
    }),
    async execute(_toolCallId, params, signal, onUpdate, ctx) {
      validateFunctionName(params.functionName);
      onUpdate?.({ content: [{ type: "text", text: `Classifying ${params.functionName}...` }], details: {} });
      return runProjectCommand(
        pi,
        ctx.cwd,
        "npx",
        ["tsx", "tools/agent/explainDiff.ts", params.functionName],
        signal,
        15_000,
      );
    },
  });
}

import { resolve } from "node:path";
import type { ExtensionAPI } from "@earendil-works/pi-coding-agent";
import { withFileMutationQueue } from "@earendil-works/pi-coding-agent";
import { Type } from "typebox";
import { runProjectCommand, validateFunctionName } from "./shared.ts";

export function registerExportContextTool(pi: ExtensionAPI): void {
  pi.registerTool({
    name: "psx_export_context",
    label: "Export PSX Context",
    description: "Export one matched function signature, or all matched signatures, into the project's generated function context header. Output is limited to 50 KB or 2000 lines.",
    parameters: Type.Object({
      functionName: Type.Optional(Type.String({ description: "Exact function symbol; omit to export all matched signatures" })),
    }),
    async execute(_toolCallId, params, signal, onUpdate, ctx) {
      if (params.functionName) validateFunctionName(params.functionName);
      onUpdate?.({
        content: [{ type: "text", text: params.functionName ? `Exporting ${params.functionName}...` : "Exporting all signatures..." }],
        details: {},
      });

      const args = ["tsx", "tools/agent/contextExport.ts", params.functionName ?? "--all"];
      const target = resolve(ctx.cwd, "include", "functions.h");
      return withFileMutationQueue(target, () =>
        runProjectCommand(pi, ctx.cwd, "npx", args, signal, 30_000),
      );
    },
  });
}

import { createTreeFromWorktree, changedFilesBetweenTrees, treePatch } from "../../shared/workspace.ts";
import { loadCallGraph } from "../../shared/call-graph.ts";
import { runGate } from "../../shared/gates.ts";
import { runCommand } from "../../shared/process.ts";
import type { AutodecompConfig, GateResult } from "../../shared/types.ts";
import { Timings } from "../../../../tools/lib/contentCache.js";
import { CONTEXT_EXPORT_STATUS, type ExportResult } from "../../../../tools/agent/contextExport.js";
import { compilerInputs, consumeReceipt, contextIsCompilerIndependent, publishReceipt, verificationOutputs } from "./verification-receipt.ts";

/** One authoritative route. Machine work can be reused only across unchanged
 * inputs/outputs in this workspace; context publication and scope still gate. */
export async function finalizeWorkspace(options: {
  projectRoot: string; config: AutodecompConfig; functionName: string;
  changedFiles: string[]; patch: string; signal?: AbortSignal;
}): Promise<GateResult> {
  options.signal?.throwIfAborted();
  const timings = new Timings();
  const gates: GateResult[] = [];
  let contextPublication: GateResult["contextPublication"];
  const done = (gate: GateResult): GateResult => ({ ...gate, ...(contextPublication ? { contextPublication } : {}), finalizationGates: gates,
    timings: { phases: timings.phases, totalMs: timings.totalMs } });
  const graph = loadCallGraph(options.projectRoot);
  const entry = graph.functions.find((f) => f.name === options.functionName);
  const gateOptions = {
    ...options, mode: "match" as const,
    ...(entry?.vram ? { functionVram: entry.vram } : {}),
    ...(entry?.container ? { functionContainer: entry.container } : {}),
    functionVrams: Object.fromEntries(graph.functions.map((f) => [f.name, f.vram])),
    functionContainers: Object.fromEntries(graph.functions.map((f) => [f.name, f.container])),
    functionSources: Object.fromEntries(graph.functions.map((f) => [f.name, f.source ?? `src/${f.name}.c`])),
  };
  const reuse = timings.measureSync("receipt-validation", () => consumeReceipt(options.projectRoot, options.functionName, options.config));
  if (reuse.gate) {
    const gate = await timings.measure("receipt-policy-scope", () => runGate({ ...gateOptions, machineVerification: reuse.gate }));
    const stillFresh = timings.measureSync("receipt-revalidation", () => consumeReceipt(options.projectRoot, options.functionName, options.config));
    if (!stillFresh.gate) { gate.pass = false; gate.failures.push(`Receipt invalidated during policy/scope check: ${stillFresh.reason}`); }
    gate.receipt = stillFresh.gate?.receipt;
    gate.cache = { hit: true, reason: reuse.reason }; gates.push(gate);
    return done(gate);
  }
  const initialInputs = timings.measureSync("initial-inputs", () => compilerInputs(options.projectRoot, true));
  const first = await timings.measure("initial-gate", () => runGate(gateOptions));
  gates.push(first);
  if (!first.pass) return done(first);
  options.signal?.throwIfAborted();
  const before = await timings.measure("before-publication-tree", () => createTreeFromWorktree(options.projectRoot, options.projectRoot, options.config.integration.allowedRoots, options.signal));
  const beforeInputs = timings.measureSync("before-publication-inputs", () => compilerInputs(options.projectRoot, true));
  const beforeOutputs = timings.measureSync("before-publication-outputs", () => verificationOutputs(options.projectRoot, options.functionName));
  const publication = await timings.measure("context-export", () => runCommand("npx", ["tsx", "tools/agent/contextExport.ts", options.functionName], {
    cwd: options.projectRoot, signal: options.signal, timeoutMs: 120_000,
  }));
  options.signal?.throwIfAborted();
  const statusLine = publication.stdout.split("\n").find((line) => line.startsWith(CONTEXT_EXPORT_STATUS));
  try {
    const result = JSON.parse(statusLine?.slice(CONTEXT_EXPORT_STATUS.length) ?? "null") as ExportResult | null;
    if (result && ["published", "skipped"].includes(result.status) && typeof result.signatureMatches === "boolean")
      contextPublication = { ...result, command: publication };
  } catch { /* A missing or malformed generator outcome cannot mean success. */ }
  if (publication.code !== 0 || !contextPublication || !contextPublication.signatureMatches) return done({ ...first, pass: false,
    failures: [`Context export failed or did not publish the definition's signature: ${contextPublication?.reason ?? "missing/failed publication outcome"}\n${publication.stdout}\n${publication.stderr}`] });
  const after = await timings.measure("after-publication-tree", () => createTreeFromWorktree(options.projectRoot, options.projectRoot, options.config.integration.allowedRoots, options.signal));
  const exportedFiles = await changedFilesBetweenTrees(options.projectRoot, before, after, options.signal);
  const afterInputs = timings.measureSync("after-publication-inputs", () => compilerInputs(options.projectRoot, true));
  const independent = contextIsCompilerIndependent(options.projectRoot);
  const afterOutputs = timings.measureSync("after-publication-outputs", () => verificationOutputs(options.projectRoot, options.functionName));
  const unchanged = initialInputs === beforeInputs && beforeInputs === afterInputs && independent && beforeOutputs === afterOutputs;
  const publicationPatch = await treePatch(options.projectRoot, before, after, options.config.integration.allowedRoots, options.signal);
  const gate = await timings.measure("publication-gate", () => runGate({ ...gateOptions,
    ...(unchanged ? { machineVerification: first } : {}),
    changedFiles: [...new Set([...options.changedFiles, ...exportedFiles])].sort(),
    patch: options.patch + "\n" + publicationPatch,
  }));
  gates.push(gate);
  gate.contextPublication = contextPublication;
  options.signal?.throwIfAborted();
  gate.cache = { hit: unchanged, reason: unchanged ? "publication changed only compiler-independent context" : "compiler inputs changed or dependency coverage incomplete" };
  if (gate.pass) {
    const finalInputs = timings.measureSync("final-inputs", () => compilerInputs(options.projectRoot, true));
    const finalOutputs = timings.measureSync("final-outputs", () => verificationOutputs(options.projectRoot, options.functionName));
    if (finalInputs !== afterInputs || (unchanged && beforeOutputs !== finalOutputs)) {
      gate.pass = false; gate.failures.push("Verification inputs changed during publication gate; rerun finalization");
    } else {
      gate.receipt = timings.measureSync("receipt-publication", () => publishReceipt(options.projectRoot, options.functionName, options.config, gate));
    }
  }
  return done(gate);
}

/** The loop may skip its preliminary diff only when this process owns a fresh
 * successful finalization. finalizeWorkspace still rechecks scope and policy. */
export function finalizedDiff(projectRoot: string, functionName: string, config: AutodecompConfig) {
  return consumeReceipt(projectRoot, functionName, config).gate?.diff;
}

import type { ExtensionAPI, ExtensionContext } from "@earendil-works/pi-coding-agent";
import { Type } from "typebox";
import { loadConfig } from "../../shared/config.ts";
import { finalizeWorkspace } from "./finalization.ts";
import { loadCallGraph } from "../../shared/call-graph.ts";
import { createTreeFromWorktree, changedFilesBetweenTrees, filterNewChanges, treePatch, workspaceChangedFiles } from "../../shared/workspace.ts";
import { getSessionBaseline } from "./session-baseline.ts";
import { validateFunctionName } from "./shared.ts";

export function registerFinalizeFunctionTool(pi: ExtensionAPI,
  onPassed?: (name: string, changedFiles: string[], ctx: ExtensionContext) => void): void {
  pi.registerTool({
    name: "psx_finalize_function",
    label: "Finalize PSX Function",
    description: "Run the exact function diff, full binary check, modification-scope check, and clean-source policy gate. A passing result terminates the autonomous worker turn.",
    parameters: Type.Object({
      functionName: Type.String({ description: "Exact function symbol to finalize" }),
    }),
    async execute(_toolCallId, params, signal, onUpdate, ctx) {
      validateFunctionName(params.functionName);
      if (signal?.aborted) throw new Error("Finalization cancelled");
      onUpdate?.({ content: [{ type: "text", text: `Finalizing ${params.functionName}...` }], details: {} });
      const config = loadConfig(ctx.cwd);
      const entry = loadCallGraph(ctx.cwd).functions.find((candidate) => candidate.name === params.functionName);
      const containerNote = entry && entry.container !== "exe" ? ` in ${entry.container}` : "";
      const tree = await createTreeFromWorktree(ctx.cwd, ctx.cwd, config.integration.allowedRoots);
      const patch = await treePatch(ctx.cwd, "HEAD", tree, config.integration.allowedRoots);
      const allChangedFiles = [...new Set([
        ...await changedFilesBetweenTrees(ctx.cwd, "HEAD", tree),
        ...await workspaceChangedFiles(ctx.cwd),
      ])].sort();
      const baseline = await getSessionBaseline(ctx.cwd);
      const { newFiles: changedFiles, preExisting } = filterNewChanges(allChangedFiles, baseline);
      /* The graph places the function; the gate needs it placed. Without the
         container and the source path the policy scan looks for an overlay's
         translation unit under `src/`, finds nothing, and reports a clean
         function it never opened. */
      const gate = await finalizeWorkspace({ projectRoot: ctx.cwd, config, functionName: params.functionName, changedFiles, patch, signal });
      const scopeNote = preExisting.length
        ? `\nScope gate ignored ${preExisting.length} pre-existing workspace change(s): ${preExisting.join(", ")}`
        : "";
      if (gate.pass) {
        const after = filterNewChanges(await workspaceChangedFiles(ctx.cwd), baseline).newFiles;
        onPassed?.(params.functionName, [...new Set([...changedFiles, ...after])].sort(), ctx);
      }
      const text = gate.pass
        ? `${params.functionName}${containerNote} passed exact diff, full build, scope, and clean-source gates.${scopeNote}`
        : `${params.functionName} failed finalization:\n${gate.failures.map((failure) => `- ${failure}`).join("\n")}${scopeNote}`;
      return {
        content: [{ type: "text", text }],
        details: gate,
        terminate: gate.pass,
      };
    },
  });
}

import type { ExtensionAPI } from "@earendil-works/pi-coding-agent";
import { Type } from "typebox";
import { runProjectCommand, validateFunctionName } from "./shared.ts";

const mechanism = Type.Union([
  Type.Literal("fresh-vs-reused-web"),
  Type.Literal("single-vs-multi-set"),
  Type.Literal("constant-birth-site"),
  Type.Literal("result-vs-input-reuse"),
  Type.Literal("address-expression-family"),
  Type.Literal("alias-dependency"),
  Type.Literal("statement-birth-order"),
  Type.Literal("custom"),
]);

function safePath(path: string): boolean {
  return !path.split("/").includes("..");
}

export function registerFuzzVariantsTool(pi: ExtensionAPI): void {
  pi.registerTool({
    name: "psx_fuzz_variants",
    label: "PSX Variant Laboratory",
    description:
      "Compile complete C variants as explicit compiler-mechanism hypotheses. Preserves source, preprocessing, assembly/object, hashes, flags, comparisons, and optional pass traces under a deterministic run directory. Reports mechanism verdicts before match percentage; no random permutation or hill climbing. Use a JSON manifest for distinct per-variant hypotheses, or provide common mechanism metadata with variants. Output is limited to 50 KB or 2000 lines.",
    parameters: Type.Object({
      functionName: Type.String({ description: "Exact function symbol the variants target" }),
      variants: Type.Optional(Type.Array(Type.String(), {
        description: "Complete variant .c paths. Requires mechanism, expectedPass, and expectedEffect; use manifest for different hypotheses per variant.",
      })),
      manifest: Type.Optional(Type.String({
        description: "JSON manifest containing id, sourcePath, mechanism, expectedPass, expectedEffect, and invariants for each variant.",
      })),
      transformSpec: Type.Optional(Type.String({
        description: "Opt-in curated transformation specification. Exact edits generate complete C89 variants under build/ before running.",
      })),
      mechanism: Type.Optional(mechanism),
      expectedPass: Type.Optional(Type.String({ description: "Compiler pass predicted to change, such as rtl, combine, sched, lreg, greg, or sched2" })),
      expectedEffect: Type.Optional(Type.String({ description: "Concrete compiler effect the supplied variants are intended to test" })),
      invariants: Type.Optional(Type.Array(Type.String(), { description: "Semantic/source properties that must remain unchanged" })),
      tracePasses: Type.Optional(Type.Boolean({ description: "Compare rtl through dbr and report the first meaningful divergence" })),
      cc1Only: Type.Optional(Type.Boolean({
        description: "Fast triage only. A cc1-only exact result is never promotion-eligible until rerun in full mode.",
      })),
      show: Type.Optional(Type.String({ description: "Variant id whose full target-versus-compiled instruction listing should be printed" })),
    }),
    async execute(_toolCallId, params, signal, onUpdate, ctx) {
      validateFunctionName(params.functionName);
      const variants = params.variants || [];
      const modes = Number(Boolean(params.manifest)) + Number(Boolean(params.transformSpec)) + Number(variants.length > 0);
      if (modes !== 1) throw new Error("Choose exactly one of variants, manifest, or transformSpec.");
      for (const path of [...variants, params.manifest, params.transformSpec].filter((value): value is string => Boolean(value))) {
        if (!safePath(path)) throw new Error(`Invalid path: ${path}`);
      }
      if (variants.length > 0 && (!params.mechanism || !params.expectedPass || !params.expectedEffect)) {
        throw new Error("Direct variants require mechanism, expectedPass, and expectedEffect. Use manifest for per-variant metadata.");
      }
      for (const variant of variants) {
        if (!variant.endsWith(".c")) throw new Error(`Variant path must end in .c: ${variant}`);
      }

      const args = ["tsx", "tools/agent/fuzzVariants.ts", params.functionName];
      if (params.manifest) args.push("--manifest", params.manifest);
      else if (params.transformSpec) args.push("--transform-spec", params.transformSpec);
      else args.push(...variants, "--mechanism", params.mechanism!, "--expected-pass", params.expectedPass!, "--expected-effect", params.expectedEffect!);
      for (const invariant of params.invariants || []) args.push("--invariant", invariant);
      if (params.tracePasses) args.push("--trace-passes");
      if (params.cc1Only) args.push("--cc1-only");
      if (params.show) args.push("--show", params.show);

      onUpdate?.({
        content: [{ type: "text", text: `Running mechanism-aware variants for ${params.functionName}...` }],
        details: {},
      });
      return runProjectCommand(pi, ctx.cwd, "npx", args, signal, 180_000);
    },
  });
}

import { existsSync, mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { join } from "node:path";
import type { ExtensionAPI, ExtensionCommandContext, ExtensionContext } from "@earendil-works/pi-coding-agent";
import { prepareAttempt, attemptStaticFinalization, buildInputs, sameInputs, inputIdentity, documentCompletion, type Completion } from "./prepared-attempt.ts";
import { finalize } from "../autoloop/oracles.ts";
import { groupingsMessage } from "../autoloop/prompts.ts";
import { getSessionBaseline } from "./session-baseline.ts";
import { randomUUID } from "node:crypto";

const completionPath = (root: string, name: string) => join(root, "build/preparation/completions", `${name}.json`);
export function saveInteractiveCompletion(root: string, name: string, completion: Completion): void {
  mkdirSync(join(root, "build/preparation/completions"), { recursive: true });
  writeFileSync(completionPath(root, name), JSON.stringify(completion, null, 2) + "\n");
}
export function agentCompletion(root: string, changedFiles: string[]): Completion {
  const inputs = buildInputs(root);
  return { origin: "agent", inputs, verifiedIdentity: inputIdentity(inputs), verification: "passed", changedFiles, documentation: "pending" };
}
export async function prepareInteractive(root: string, name: string, ctx: ExtensionCommandContext, signal: AbortSignal): Promise<{
  handoff: string; completion?: Completion;
}> {
  signal.throwIfAborted();
  const path = completionPath(root, name);
  if (existsSync(path)) {
    const prior = JSON.parse(readFileSync(path, "utf8")) as Completion;
    if (sameInputs(prior.inputs, buildInputs(root))) return { handoff: "", completion: prior };
  }
  await waitForPreparationIdle(ctx, signal);
  const attempt = await prepareAttempt(root, name, signal);
  signal.throwIfAborted();
  const baseline = await getSessionBaseline(root);
  signal.throwIfAborted();
  const result = await attemptStaticFinalization({ root, attempt, aborted: () => signal.aborted,
    finalize: async () => {
      const result = await finalize({ projectRoot: root, baseline, state: { parked: {}, approvals: {} }, signal }, name);
      return { passed: result.passed, changedFiles: result.changedFiles, detail: result.gate.failures.join("; ") };
    } });
  signal.throwIfAborted();
  if (result.completed) saveInteractiveCompletion(root, name, result.completed);
  return { handoff: result.handoff, ...(result.completed ? { completion: result.completed } : {}) };
}

/** Idle commands have no ctx.signal. Own cancellation until the last dispatch;
 * shutdown awaits child cleanup, and a second command never starts another job. */
export function interactivePreparationLifecycle(pi: ExtensionAPI) {
  let active: { controller: AbortController; done: Promise<void> } | undefined;
  let closed = false;
  const cancel = async () => {
    const own = active;
    if (!own) return false;
    own.controller.abort();
    await own.done;
    return true;
  };
  pi.on("session_shutdown", async () => { closed = true; await cancel(); });
  pi.on("session_start", () => { closed = false; });
  return {
    cancel,
    async run(ctx: Pick<ExtensionContext, "signal" | "ui">, work: (signal: AbortSignal) => Promise<void>): Promise<void> {
      if (closed) return;
      if (active) { ctx.ui.notify("Preparation already running. Use /decompile --cancel or /fix-decomp --cancel first.", "warning"); return; }
      const controller = new AbortController();
      const abort = () => controller.abort();
      ctx.signal?.addEventListener("abort", abort, { once: true });
      if (ctx.signal?.aborted) abort();
      const own = { controller, done: Promise.resolve() };
      active = own;
      own.done = Promise.resolve().then(async () => {
        controller.signal.throwIfAborted();
        await work(controller.signal);
      }).catch((error) => {
        if (controller.signal.aborted) ctx.ui.notify("Preparation cancelled; no solver or documentation dispatched.", "info");
        else ctx.ui.notify(`Preparation command failed: ${String(error)}`, "error");
      }).finally(() => {
        ctx.signal?.removeEventListener("abort", abort);
        if (active === own) active = undefined;
      });
      await own.done;
    },
  };
}

export async function waitForPreparationIdle(ctx: Pick<ExtensionCommandContext, "waitForIdle">, signal: AbortSignal): Promise<void> {
  signal.throwIfAborted();
  let abort: () => void = () => {};
  const cancelled = new Promise<never>((_resolve, reject) => {
    abort = () => reject(signal.reason);
    signal.addEventListener("abort", abort, { once: true });
  });
  try { await Promise.race([ctx.waitForIdle(), cancelled]); signal.throwIfAborted(); }
  finally { signal.removeEventListener("abort", abort); }
}

/** One explicit notes-only role, with durable pending state and input protection. */
export function interactiveDocumentation(pi: ExtensionAPI, root: string): {
  start: (name: string, completion: Completion, ctx: Pick<ExtensionContext, "model" | "ui" | "isIdle">) => void;
} {
  let pending: { name: string; completion: Completion; marker: string; started: boolean; succeeded: boolean } | undefined;
  pi.on("before_agent_start", (event) => {
    if (!pending) return;
    if (!event.prompt.includes(pending.marker)) {
      saveInteractiveCompletion(root, pending.name, { ...pending.completion, documentation: "pending", error: "documentation interrupted by another request" });
      pending = undefined; return;
    }
    pending.started = true;
    pending.succeeded = false;
  });
  pi.on("agent_end", (event) => {
    if (!pending?.started) return;
    const last = [...event.messages].reverse().find((m) => m.role === "assistant");
    pending.succeeded = last?.role === "assistant" && last.stopReason === "stop";
  });
  pi.on("agent_settled", async (_event, ctx) => {
    if (!pending?.started) return;
    const own = pending; pending = undefined;
    const result = await documentCompletion(root, own.completion, async () => own.succeeded);
    saveInteractiveCompletion(root, own.name, result);
    if (result.documentation !== "passed") ctx.ui.notify(`${own.name}: documentation pending — ${result.error}`, "warning");
  });
  return { start(name, completion, ctx) {
    saveInteractiveCompletion(root, name, completion);
    if (completion.documentation === "passed") { ctx.ui.notify(`${name} is already finalized and documented.`, "info"); return; }
    if (!ctx.model) { ctx.ui.notify(`${name} finalized; documentation pending (no model available).`, "warning"); return; }
    if (pending) { ctx.ui.notify(`${name}: documentation pending; another documentation turn is active.`, "warning"); return; }
    const marker = `Documentation attempt: ${randomUUID()}`;
    pending = { name, completion, marker, started: false, succeeded: false };
    pi.sendUserMessage(groupingsMessage(name) + `\n${marker}. Verified identity: ${completion.verifiedIdentity}. Changed files: ${completion.changedFiles.join(", ")}.`,
      ctx.isIdle() ? undefined : { deliverAs: "followUp" });
  } };
}

import { resolve } from "node:path";
import type { ExtensionAPI } from "@earendil-works/pi-coding-agent";
