export function registerM2cTool(pi: ExtensionAPI): void {
  pi.registerTool({
    name: "psx_m2c",
    label: "PSX m2c",
    description: "Prepare faithful context and a measured m2c handoff under build/. Preserve raw output, complete diagnostics and explicit unknowns; an existing clean-C attempt remains primary. Output is limited to 50 KB or 2000 lines.",
    parameters: Type.Object({
      functionName: Type.String({ description: "Exact function symbol to decompile" }),
      alternative: Type.Optional(Type.Boolean({ description: "Explicitly generate an m2c alternative to an existing attempt" })),
      stage: Type.Optional(Type.Boolean({ description: "Safely stage a compiling candidate into an unchanged committed target stub" })),
    }),
    async execute(_toolCallId, params, signal, onUpdate, ctx) {
      validateFunctionName(params.functionName);
      onUpdate?.({ content: [{ type: "text", text: `Running m2c for ${params.functionName}...` }], details: {} });
      /* Lock the file m2c will actually write. Queuing on `src/<name>.c` for an
         overlay function guards a path nothing touches, so two writers to the
         real file would not serialise against each other. */
      const target = resolve(ctx.cwd, functionPaths(ctx.cwd, params.functionName).source);
      return withFileMutationQueue(target, () =>
        runProjectCommand(
          pi,
          ctx.cwd,
          "npx",
          ["tsx", "tools/agent/m2cFunc.ts", params.functionName, ...(params.alternative ? ["--alternative"] : []), ...(params.stage ? ["--write"] : [])],
          signal,
          600_000,
        ),
      );
    },
  });
}

import { existsSync, readFileSync, readdirSync, writeFileSync } from "node:fs";
import { dirname, join, relative } from "node:path";
import { withFileMutationQueue } from "@earendil-works/pi-coding-agent";
import { recordedCommand, commandText } from "../../../../tools/lib/recordedCommand.ts";
import { hashFile, hashText, packetIsFresh, stagePrepared } from "../../../../tools/agent/prepareFunction.ts";
import { loadContainers } from "../../../../tools/lib/container.ts";
import { configuredToolchainIdentity } from "../../../../tools/agent/decompToolchain.ts";
import { packetOpening, packetEvidence, type PreparationPacket } from "../../../../tools/agent/campaign/packet.ts";

export interface PreparedAttempt { packet: PreparationPacket; path: string }
export async function prepareAttempt(root: string, name: string, signal?: AbortSignal): Promise<PreparedAttempt> {
  const result = await recordedCommand("npx", ["tsx", "tools/agent/m2cFunc.ts", name, "--json"], root,
    join(root, "build/preparation/commands", name, `${Date.now()}-${process.pid}`), "prepare", signal, 600_000);
  if (result.status !== 0) throw new Error(`Preparation failed; full diagnostics: ${result.stderr}\n${commandText(result)}`);
  const { path } = JSON.parse(readFileSync(result.stdout, "utf8")) as { path: string };
  return { path, packet: JSON.parse(readFileSync(join(root, path), "utf8")) as PreparationPacket };
}
export function persistAttempt(root: string, attempt: PreparedAttempt): void {
  writeFileSync(join(root, attempt.path), JSON.stringify(attempt.packet, null, 2) + "\n");
  writeFileSync(join(root, dirname(attempt.path), "handoff.md"), packetOpening(attempt.packet, attempt.path) + "\n");
  writeFileSync(join(root, dirname(attempt.path), "evidence.md"), packetEvidence(attempt.packet) + "\n");
  writeFileSync(join(root, dirname(attempt.path), "diagnostics.txt"), attempt.packet.compilation.diagnostics + "\n");
}

export function buildInputs(root: string): Record<string, string> {
  const inputs: Record<string, string> = {};
  const visit = (path: string) => {
    if (!existsSync(path)) return;
    for (const e of readdirSync(path, { withFileTypes: true }).sort((a, b) => a.name.localeCompare(b.name))) {
      const file = join(path, e.name);
      if (e.isDirectory()) visit(file); else inputs[relative(root, file)] = hashFile(file);
    }
  };
  for (const dir of ["src", "include", "configs", "tools/agent", "tools/build", "tools/lib", ".pi/extensions/psx-decomp", ".pi/extensions/shared", "tools/vendor/m2c/m2c", "tools/vendor/m2c/m2c_pycparser", "tools/vendor/m2c-patches", "tools/vendor/maspsx/maspsx", "tools/vendor/tree-sitter-c"]) visit(join(root, dir));
  const tools = configuredToolchainIdentity();
