          const skill = readFileSync(new URL("../../skills/psx-build-resource-parser/SKILL.md", import.meta.url), "utf8");
          await ctx.waitForIdle(); state.controller.signal.throwIfAborted();
          const before = gate.settled; state.ownsTurn = true;
          timer = setTimeout(() => stop(ctx), 20 * 60 * 1000);
          pi.sendUserMessage(`${skill}\n\nWork item: ${args}\nPrepared baseline: ${state.binding.baseline}. Finish with action=test, then action=accept. Success is a tested capability, not an asset note or a commit. Stop honestly if the required evidence is missing.`);
          const result = await waitForTurn({ gate, before, isIdle: () => ctx.isIdle(), isAborted: () => state.controller.signal.aborted, waitForIdle: () => ctx.waitForIdle(), startTimeoutMs: 120000, pollMs: 50, now: () => Date.now(), sleep: ms => new Promise(r => setTimeout(r, ms)) });
          if (result !== "settled") throw new Error(`Parser turn ${result}`);
          if (state.alive) message(state.binding.finish ? "Parser capability tested. Run npm run extract-assets to regenerate supported exports; nothing committed." : "Parser work ended without an accepted test gate; drafts remain for inspection. Nothing committed.");
        } finally {
          if (timer) clearTimeout(timer);
          if (state.alive) { if (state.controller.signal.aborted && state.ownsTurn) await ctx.abort(); pi.setActiveTools(saved); }
          state.ownsTurn = false;
        }
      });
    },
  });
  return { binding: () => active?.binding };
}

import { existsSync } from "node:fs";
import { dirname, join, resolve } from "node:path";
import type { ExtensionAPI } from "@earendil-works/pi-coding-agent";
import { registerResourceCommand } from "./controller.ts";
import { registerResourceTools } from "./tools/index.ts";

export function projectRoot(start: string): string {
  let root = resolve(start);
  while (true) {
    if (existsSync(join(root, "AGENTS.md")) && existsSync(join(root, "tools/agent"))) return root;
    const parent = dirname(root);
    if (parent === root) return resolve(start);
    root = parent;
  }
}
export default function psxResources(pi: ExtensionAPI): void {
  const harness = registerResourceCommand(pi, projectRoot);
  registerResourceTools(pi, harness.binding, projectRoot);
}

import type { ExtensionAPI } from "@earendil-works/pi-coding-agent";
import { runResource } from "./runner.ts";
import type { Request } from "../../../../tools/agent/resource-extraction/types.ts";
import { bindRequest, TOOL_SPECS, type RoleBinding } from "./specs.ts";

export function boundedReport(value: unknown): string {
  const text = JSON.stringify(value, null, 2), lines = text.split("\n");
  const prefix = Buffer.from(lines.slice(0, 900).join("\n"));
  let result = prefix.subarray(0, 45000).toString("utf8");
  if (lines.length > 900 || prefix.length > 45000) result += `\n[Truncated to 900 lines/45 KB. Full report: ${(value as { fullReport?: string }).fullReport ?? "build/assets/manifest.json"}]`;
  return result;
}
export function registerResourceTools(pi: ExtensionAPI, getBinding: () => RoleBinding | undefined, projectRoot: (cwd: string) => string): void {
  for (const spec of TOOL_SPECS) pi.registerTool({
    name: spec.name, label: `Resources: ${spec.operation}`, description: `${spec.description} Output bounded to 900 lines/45 KB.`, parameters: spec.parameters,
    async execute(_toolCallId, params, signal, onUpdate, ctx) {
      const binding = getBinding(), request = bindRequest(binding, spec.operation, params as Request);
      const combined = AbortSignal.any([signal, binding?.controller.signal].filter((s): s is AbortSignal => Boolean(s)));
      let lastUpdate = 0;
      const result = await runResource(spec.operation, projectRoot(ctx.cwd), request, combined, info => {
        if (Date.now() - lastUpdate < 150) return; lastUpdate = Date.now();
        onUpdate?.({ content: [{ type: "text", text: boundedReport(info) }], details: {} });
      });
      const terminate = Boolean(binding && spec.operation === "parser" && result.outcome === "parser-tested");
      if (terminate) binding!.finish = true;
      return { content: [{ type: "text", text: boundedReport(result) }], details: result, ...(terminate ? { terminate: true } : {}) };
    },
  });
}

import { spawn } from "node:child_process";
import { existsSync } from "node:fs";
import { dirname, resolve } from "node:path";
import { fileURLToPath } from "node:url";
import { canonical, hash, Store } from "../../../../tools/agent/resource-extraction/storage.ts";
import { TOOL_SCRIPTS, type Operation, type Request } from "../../../../tools/agent/resource-extraction/types.ts";

/** Fresh deterministic process, not an agent. Stdin replaces persistent request
 * files; successful invocations need no command transcript/acceptance ledger.
 * Newly registered parser modules are picked up without a TUI reload. */
export async function runResource(operation: Operation, root: string, request: Request = {}, signal?: AbortSignal, progress?: (info: Record<string, unknown>) => void): Promise<Record<string, unknown>> {
  signal?.throwIfAborted();
  const repository = resolve(dirname(fileURLToPath(import.meta.url)), "../../../..");
  const script = TOOL_SCRIPTS.find(([key]) => key === operation)?.[1];
  if (!script) throw new Error("Unknown resource operation");
  const localScript = resolve(root, "tools/agent", script);
  const executable = existsSync(localScript) ? localScript : resolve(repository, "tools/agent", script);
  const payload = canonical(request);
  if (Buffer.byteLength(payload) > 65536) throw new Error("Request budget exceeded");
  const env = { ...process.env }; delete env.NODE_TEST_CONTEXT;
  return new Promise((resolveResult, reject) => {
    const child = spawn(process.execPath, [resolve(repository, "node_modules/tsx/dist/cli.mjs"), executable, "--request", "-"], { cwd: root, env, stdio: ["pipe", "pipe", "pipe"] });
    let stdout = "", stderr = "", buffered = "", result: Record<string, unknown> | undefined, cancelled = false;
    let force: ReturnType<typeof setTimeout> | undefined;
    const cancel = (): void => { cancelled = true; child.kill("SIGTERM"); force ??= setTimeout(() => child.kill("SIGKILL"), 2000); };
    const deadline = setTimeout(cancel, 180000);
    signal?.addEventListener("abort", cancel);
    child.stdin.on("error", () => {}); child.stdin.end(payload);
    child.stdout.on("data", chunk => {
      const text = chunk.toString(); stdout += text; buffered += text;
      if (stdout.length > 16 * 1024 * 1024) { cancel(); return; }
      let newline: number;
      while ((newline = buffered.indexOf("\n")) >= 0) {
        const line = buffered.slice(0, newline); buffered = buffered.slice(newline + 1);
        try {
          const message = JSON.parse(line);
          if (message.type === "progress") progress?.(message);
          if (message.type === "result") result = message.result;
        } catch { /* Nonprotocol diagnostics are captured only on failure. */ }
      }
    });
    child.stderr.on("data", chunk => { stderr += chunk.toString(); if (stderr.length > 4 * 1024 * 1024) cancel(); });
    child.once("error", reject);
    child.once("close", code => {
      clearTimeout(deadline); if (force) clearTimeout(force); signal?.removeEventListener("abort", cancel);
      if (cancelled || code !== 0 || !result) {
        const store = new Store(root), report = { operation, request, code, cancelled, stdout, stderr };
        const path = `cache/diagnostics/${hash(canonical(report))}.json`; store.json(path, report);
        reject(new Error(`${operation} ${cancelled ? "cancelled/timed out" : "failed"}: ${stderr.slice(-12000)}. Diagnostic: build/assets/${path}`));
      } else resolveResult(result);
    });
  });
}

import { StringEnum } from "@earendil-works/pi-ai";
import { Type } from "typebox";
import type { Operation, Request } from "../../../../tools/agent/resource-extraction/types.ts";

const limits = Type.Object(Object.fromEntries(["maxFiles", "maxInputBytes", "maxFileBytes", "maxAssets", "maxOutputBytes", "maxFunctions", "maxInstructions"].map(key => [key, Type.Optional(Type.Integer({ minimum: 1 }))])), { additionalProperties: false });
const field = Type.Object({ offset: Type.Integer({ minimum: 0 }), width: Type.Integer({ minimum: 1, maximum: 4 }), endian: StringEnum(["le", "be"] as const), scale: Type.Integer({ minimum: 1 }), signed: Type.Boolean() }, { additionalProperties: false });
const schema = Type.Object({ index: Type.String(), data: Type.String(), tableOffset: Type.Integer({ minimum: 0 }), count: Type.Integer({ minimum: 0, maximum: 1000000 }), stride: Type.Integer({ minimum: 1, maximum: 65536 }), base: Type.Integer({ minimum: 0 }), position: field, length: field, basis: StringEnum(["supplied-hypothesis"] as const) }, { additionalProperties: false });
export const TOOL_SPECS = [
  { operation: "extract", script: "resourceExtract.ts", name: "psx_resource_extract", description: "Run the deterministic extractor: flat content-deduplicated exports, checked caches and generated provenance. No model, iteration, run ID or commit.", parameters: Type.Object({ input: Type.Optional(Type.String()), limits: Type.Optional(limits), schemas: Type.Optional(Type.Array(schema, { maxItems: 128 })), transforms: Type.Optional(Type.Array(Type.Object({ input: Type.String(), code: Type.String(), address: Type.Integer({ minimum: 0, maximum: 4294967295 }), kind: StringEnum(["byte-xor"] as const) }, { additionalProperties: false }), { maxItems: 128 })), force: Type.Optional(Type.Boolean()), fullVerify: Type.Optional(Type.Boolean()) }, { additionalProperties: false }) },
  { operation: "verify", script: "resourceVerify.ts", name: "psx_resource_verify", description: "Read-only full replay of the current manifest, exports and generated document. Decode once per variant; report drift/corruption without repair.", parameters: Type.Object({}, { additionalProperties: false }) },
  { operation: "analyze", script: "resourceAnalyze.ts", name: "psx_resource_analyze", description: "Inspect one original file under extracted/: bounded hex view and original-word CFG/SSA evidence. No compiler, matched source or guessed format meaning.", parameters: Type.Object({ input: Type.String(), offset: Type.Optional(Type.Integer({ minimum: 0 })), length: Type.Optional(Type.Integer({ minimum: 0, maximum: 4096 })), limits: Type.Optional(limits) }, { additionalProperties: false }) },
  { operation: "parser", script: "resourceParser.ts", name: "psx_resource_parser", description: "Prepare a parser-only baseline or policy/typecheck/test a capability. Fixed argv, source-drift checks, no Git operations or automatic restoration/commits.", parameters: Type.Object({ action: StringEnum(["prepare", "test", "accept"] as const), baseline: Type.Optional(Type.String({ pattern: "^[a-f0-9]{24}$" })) }, { additionalProperties: false }) },
] as const;
export interface RoleBinding { baseline: string; controller: AbortController; calls: number; finish?: boolean }
export function bindRequest(binding: RoleBinding | undefined, operation: Operation, request: Request): Request {
  if (!binding) return request;
  binding.controller.signal.throwIfAborted();
  if (++binding.calls > 64) { binding.controller.abort(new Error("Parser work-item tool budget reached")); throw new Error("Parser work-item tool budget reached"); }
  if (!["parser", "analyze", "extract"].includes(operation)) throw new Error("Parser work item uses only original-byte analysis, parser tests and deterministic integration extraction");
  if (operation === "parser") {
    if (request.action === "prepare") throw new Error("Controller owns parser baseline preparation");
    if (request.baseline && request.baseline !== binding.baseline) throw new Error("Wrong parser baseline");
    return { ...request, baseline: binding.baseline };
  }
  return request;
}

import { readFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import type { ExtensionAPI } from "@earendil-works/pi-coding-agent";
import { withFileMutationQueue } from "@earendil-works/pi-coding-agent";
import { StringEnum } from "@earendil-works/pi-ai";
import { Type } from "typebox";
import { applyScaffold, formatScaffoldReport, planScaffold, provisionScaffoldVendors } from "../../../tools/build/scaffoldProject.js";

/** Loading installed resources writes nothing. Bootstrap creates only project
 * configuration/inputs; matching extensions keep their installed identity. */
export default function psxBootstrap(pi: ExtensionAPI): void {
  pi.registerTool({
    name: "psx_bootstrap_project",
    label: "Bootstrap PSX Project",
    description: "Scaffold the current repository from the installed harness package. Defaults to exe; library selects ELF/ar targets. Preserves project configuration and inputs, merges npm scripts/dependencies and .gitignore, refuses implementation collisions. Obtains missing pinned public tooling sources automatically; no game/SDK downloads or target verification. Reload Pi after scaffolding. Output is a bounded supply checklist.",
    parameters: Type.Object({
      mode: Type.Optional(StringEnum(["exe", "library"] as const)),
      dryRun: Type.Optional(Type.Boolean({ description: "Inspect the scaffold without writing anything" })),
    }),
    async execute(_id, params, signal, _update, ctx) {
      signal?.throwIfAborted();
      const plan = planScaffold(ctx.cwd, params.mode ?? "exe");
      await provisionScaffoldVendors(plan, { dryRun: params.dryRun ?? false, ...(signal ? { signal } : {}) });
      const report = await applyScaffold(plan, params.dryRun ?? false, async (path, action) => {
        await withFileMutationQueue(path, async () => { signal?.throwIfAborted(); action(); });
      });
      return { content: [{ type: "text", text: formatScaffoldReport(report) }],
        details: { root: report.root, mode: report.mode, dryRun: report.dryRun,
          created: report.created.length, updated: report.updated.length, preserved: report.preserved.length } };
    },
  });
  pi.registerCommand("psx-bootstrap", {
    description: "Bootstrap a PSX repository (exe by default; library for ELF/ar)",
    getArgumentCompletions: prefix => ["exe", "library"].filter(mode => mode.startsWith(prefix.trim())).map(mode => ({ value: mode, label: mode })),
    handler: async (args, ctx) => {
      const mode = args.trim() || "exe";
      if (mode !== "exe" && mode !== "library") { ctx.ui.notify("Usage: /psx-bootstrap [exe|library]", "warning"); return; }
      // Inline the skill for hosts whose sendUserMessage does not expand slash
      // commands. Include its location so relative references remain package-bound.
      const location = new URL("../../skills/psx-bootstrap-project/SKILL.md", import.meta.url);
      const skill = readFileSync(location, "utf8");
      pi.sendUserMessage(`Skill location: ${fileURLToPath(location)}\n\n${skill}\n\nUser: ${mode}`,
        ctx.isIdle() ? undefined : { deliverAs: "followUp" });
    },
  });
}
